async function m8SortTimeline() {
  // M8 diagnostic (Mac M2 tests, D3 check): the timeline of the 22 profiled
  // transparent-sort passes at N = 100 000 on HEAD. The scene is the one of
  // docs/plans/assets/2026-09-27-transparent-sort-bench.js (same PRNG seeds,
  // same quads, same 1920x1080 target, lighting off). After the bench's
  // 120-frame warm-up, a TEMPORARY in-page wrapper on the live profiler
  // (`consume`, to know the frame's pairs, and `history.record`, which receives
  // the frame's resolved stamps) records the name and the stamps of every
  // measured pass for RECORD_MS, then is removed (own properties deleted, the
  // prototype methods are back). No engine code changes.
  const WIDTH = 1920;
  const HEIGHT = 1080;
  const QUAD_PX = 16;
  const WINDOW = 120;
  const N = 100000;
  const RECORD_MS = 1500;
  const FULL_FRAMES = 2;
  const TIMEOUT_MS = 180000;
  const SORT_PREFIX = 'transparent-sort/';

  const engine = window.__hyperion;
  if (!engine) throw new Error('window.__hyperion is missing: open the dev harness');
  if (!new URLSearchParams(location.search).has('bench')) throw new Error('run on a ?bench page');
  if (!engine.gpuProfilingSupported) throw new Error('no timestamp-query on this device');
  if (typeof engine.getGpuFrameTiming !== 'function') throw new Error('engine.getGpuFrameTiming() is missing');
  const zModes = (window.__diagOpts && window.__diagOpts.zModes) || ['same', 'distinct'];

  const frames = (n) => new Promise((resolve) => {
    const step = (left) => (left <= 0 ? resolve() : requestAnimationFrame(() => step(left - 1)));
    step(n);
  });
  const gpuCount = () => new Promise((resolve) => {
    const hook = (_dt, views) => {
      engine.removeHook('frameEnd', hook);
      resolve(views ? views.entityCount : 0);
    };
    engine.addHook('frameEnd', hook);
  });
  const until = async (what, predicate) => {
    const start = performance.now();
    while (!(await predicate())) {
      if (performance.now() - start > TIMEOUT_MS) throw new Error(`timed out after ${TIMEOUT_MS} ms waiting for ${what}`);
      await frames(1);
    }
  };
  const settledAt = (n) => until(`${n} entities on the GPU`, async () => engine.stats.overflowCount === 0 && (await gpuCount()) === n);
  const prng = (seed) => () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const stats = (values) => {
    const v = values.filter((x) => Number.isFinite(x)).slice().sort((a, b) => a - b);
    if (v.length === 0) return null;
    const mean = v.reduce((s, x) => s + x, 0) / v.length;
    const q = (p) => v[Math.min(v.length - 1, Math.floor(p * (v.length - 1) + 0.5))];
    return { n: v.length, mean: +mean.toFixed(3), median: +q(0.5).toFixed(3), p10: +q(0.1).toFixed(3), p90: +q(0.9).toFixed(3), min: +v[0].toFixed(3), max: +v[v.length - 1].toFixed(3) };
  };
  const us = (ns) => Number(ns) / 1000;

  engine.lighting.setBackend('off');
  engine.resize(WIDTH, HEIGHT);
  engine.cam.position(0, 0, 0);
  engine.cam.zoom(1);
  await settledAt(0);
  await frames(4);
  const vp = engine.cam.viewProjection;
  const halfW = 1 / vp[0];
  const halfH = 1 / vp[5];
  const size = (QUAD_PX * 2 * halfW) / WIDTH;
  const spanX = halfW - size / 2;
  const spanY = halfH - size / 2;

  const cases = [];
  for (const zMode of zModes) {
    // The bench's scene, case (N, zMode).
    const rand = prng(N * 2 + (zMode === 'distinct' ? 1 : 0));
    const depths = new Float64Array(N);
    if (zMode === 'distinct') {
      const order = Array.from({ length: N }, (_, i) => i);
      for (let i = N - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [order[i], order[j]] = [order[j], order[i]];
      }
      for (let i = 0; i < N; i++) depths[i] = (order[i] * 999) / (N - 1);
    }
    const handles = [];
    engine.batch(() => {
      for (let i = 0; i < N; i++) {
        const h = engine.spawn({ mode: '2d' })
          .position((rand() * 2 - 1) * spanX, (rand() * 2 - 1) * spanY)
          .scale(size, size)
          .transparent();
        if (zMode === 'distinct') h.depth(depths[i]);
        handles.push(h);
      }
    });
    await settledAt(N);
    await frames(8);
    if (!engine.enableGpuProfiling()) throw new Error('enableGpuProfiling() returned false');
    const forwardSamples = () => engine.getGpuTimings().find((t) => t.name === 'forward')?.sampleCount ?? 0;
    await until(`the ${WINDOW}-frame window`, async () => forwardSamples() >= WINDOW);

    // --- the temporary wrapper ---
    const prof = engine.renderer?.graph?.profiler;
    if (!prof || typeof prof.consume !== 'function' || !prof.history || typeof prof.history.record !== 'function') {
      throw new Error('the live profiler is not reachable at engine.renderer.graph.profiler');
    }
    const hist = prof.history;
    const protoConsume = Object.getPrototypeOf(prof).consume;
    const protoRecord = Object.getPrototypeOf(hist).record;
    if (Object.prototype.hasOwnProperty.call(prof, 'consume') || Object.prototype.hasOwnProperty.call(hist, 'record')) {
      throw new Error('a wrapper is already installed');
    }
    const recorded = [];
    let consumed = 0;
    let current = null;
    prof.consume = function wrappedConsume(entry) {
      consumed++;
      current = entry;
      try {
        return protoConsume.call(this, entry);
      } finally {
        current = null;
      }
    };
    hist.record = function wrappedRecord(stamps) {
      if (current) {
        const stale = new Array(stamps.length);
        for (let i = 0; i < stamps.length; i++) stale[i] = this.known[i] === 1 && this.last[i] === stamps[i];
        recorded.push({
          pairs: current.pairs.map((p) => ({ name: p.name, work: p.work })),
          stamps: Array.from(stamps),
          stale,
          generation: current.generation,
        });
      }
      return protoRecord.call(this, stamps);
    };
    const recordStart = performance.now();
    let recordEnd;
    try {
      while (performance.now() - recordStart < RECORD_MS) await frames(1);
    } finally {
      recordEnd = performance.now();
      delete prof.consume;
      delete hist.record;
    }
    const removed = !Object.prototype.hasOwnProperty.call(prof, 'consume') && !Object.prototype.hasOwnProperty.call(hist, 'record')
      && prof.consume === protoConsume && hist.record === protoRecord;
    const timings = engine.getGpuTimings();
    const frameTiming = engine.getGpuFrameTiming();
    const discardReasons = prof.discardReasons;
    const gpuEntityCount = await gpuCount();

    // --- analysis, per recorded frame ---
    const summaries = [];
    const full = [];
    let invalid = 0;
    const passesPerFrame = new Set();
    for (let f = 0; f < recorded.length; f++) {
      const { pairs, stamps, stale } = recorded[f];
      passesPerFrame.add(pairs.length);
      let valid = true;
      let t0 = null;
      let tEnd = null;
      for (let k = 0; k < pairs.length; k++) {
        if (!pairs[k].work) continue;
        const b = stamps[2 * k];
        const e = stamps[2 * k + 1];
        if (b === 0n || e === 0n || e < b || stale[2 * k] || stale[2 * k + 1]) valid = false;
        if (t0 === null || b < t0) t0 = b;
        if (tEnd === null || e > tEnd) tEnd = e;
      }
      if (!valid || t0 === null) {
        invalid++;
        continue;
      }
      const rows = pairs.map((p, k) => ({
        name: p.name,
        work: p.work,
        beginUs: +us(stamps[2 * k] - t0).toFixed(3),
        endUs: +us(stamps[2 * k + 1] - t0).toFixed(3),
        durUs: +us(stamps[2 * k + 1] - stamps[2 * k]).toFixed(3),
      }));
      const sort = rows.filter((r) => r.work && r.name.startsWith(SORT_PREFIX));
      const cull = rows.find((r) => r.name === 'cull');
      const forward = rows.find((r) => r.name === 'forward');
      const fxaa = rows.find((r) => r.name === 'fxaa-tonemap');
      if (sort.length === 0) {
        invalid++;
        continue;
      }
      const firstBegin = Math.min(...sort.map((r) => r.beginUs));
      const lastEnd = Math.max(...sort.map((r) => r.endUs));
      const sumDur = sort.reduce((s, r) => s + r.durUs, 0);
      // Union of the sort intervals, and how they chain in encoding order.
      const byBegin = sort.slice().sort((a, b) => a.beginUs - b.beginUs);
      let union = 0;
      let curB = byBegin[0].beginUs;
      let curE = byBegin[0].endUs;
      for (const r of byBegin.slice(1)) {
        if (r.beginUs > curE) {
          union += curE - curB;
          curB = r.beginUs;
          curE = r.endUs;
        } else if (r.endUs > curE) {
          curE = r.endUs;
        }
      }
      union += curE - curB;
      let beginsBeforePrevEnd = 0;
      let endsInOrder = 0;
      let gaps = 0;
      for (let i = 1; i < sort.length; i++) {
        if (sort[i].beginUs < sort[i - 1].endUs) beginsBeforePrevEnd++;
        else gaps += sort[i].beginUs - sort[i - 1].endUs;
        if (sort[i].endUs >= sort[i - 1].endUs) endsInOrder++;
      }
      const cullEnd = cull ? cull.endUs : 0;
      const chainStart = Math.max(cullEnd, firstBegin);
      summaries.push({
        frame: f,
        spanUs: +us(tEnd - t0).toFixed(3),
        sortPasses: sort.length,
        sortSumDurUs: +sumDur.toFixed(3),
        sortFirstBeginUs: firstBegin,
        sortLastEndUs: lastEnd,
        sortFirstBeginToLastEndUs: +(lastEnd - firstBegin).toFixed(3),
        cullEndUs: cullEnd,
        sortCullEndToLastEndUs: +(lastEnd - chainStart).toFixed(3),
        sortUnionUs: +union.toFixed(3),
        sortBeginsBeforePrevEnd: beginsBeforePrevEnd,
        sortEndsInEncodingOrder: endsInOrder,
        sortGapsUs: +gaps.toFixed(3),
        gatherEndUs: sort[0].endUs,
        forwardBeginUs: forward ? forward.beginUs : null,
        forwardEndUs: forward ? forward.endUs : null,
        fxaaBeginUs: fxaa ? fxaa.beginUs : null,
        fxaaEndUs: fxaa ? fxaa.endUs : null,
      });
      full.push({ frame: f, rows });
    }
    const pick = (key) => stats(summaries.map((s) => s[key]));
    cases.push({
      N,
      zMode,
      gpuEntityCount,
      recordMs: +(recordEnd - recordStart).toFixed(1),
      consumedFrames: consumed,
      recordedFrames: recorded.length,
      validFrames: summaries.length,
      invalidFrames: invalid,
      passesPerFrame: [...passesPerFrame],
      wrapperRemoved: removed,
      discardReasons,
      profilerWindow: {
        span: frameTiming,
        entries: Object.fromEntries(timings.map((t) => [t.name, { averageMs: t.averageMs, sampleCount: t.sampleCount }])),
        sort: ['gather', 'upsweep', 'scan', 'scatter'].reduce((s, st) => s + (timings.find((t) => t.name === SORT_PREFIX + st)?.averageMs ?? NaN), 0),
      },
      stats: {
        spanUs: pick('spanUs'),
        sortSumDurUs: pick('sortSumDurUs'),
        sortFirstBeginToLastEndUs: pick('sortFirstBeginToLastEndUs'),
        sortCullEndToLastEndUs: pick('sortCullEndToLastEndUs'),
        sortUnionUs: pick('sortUnionUs'),
        sortBeginsBeforePrevEnd: pick('sortBeginsBeforePrevEnd'),
        sortEndsInEncodingOrder: pick('sortEndsInEncodingOrder'),
        sortGapsUs: pick('sortGapsUs'),
        cullEndUs: pick('cullEndUs'),
        sortFirstBeginUs: pick('sortFirstBeginUs'),
        sortLastEndUs: pick('sortLastEndUs'),
        forwardBeginUs: pick('forwardBeginUs'),
        forwardEndUs: pick('forwardEndUs'),
        fxaaBeginUs: pick('fxaaBeginUs'),
        fxaaEndUs: pick('fxaaEndUs'),
      },
      frames: summaries,
      fullFrames: full.slice(-FULL_FRAMES),
    });

    engine.disableGpuProfiling();
    for (const h of handles) h.destroy();
    await settledAt(0);
    await frames(4);
  }

  return {
    format: 'hyperion-m8-sort-timeline/1',
    what: 'Timeline of the profiled transparent-sort passes at N = 100 000 (bench scene), from a temporary in-page wrapper on the live profiler (consume + history.record), removed after RECORD_MS; times in us from the first measured beginning of each frame',
    mode: engine.mode,
    search: location.search,
    canvas: [document.getElementById('canvas').width, document.getElementById('canvas').height],
    dpr: window.devicePixelRatio,
    recordMs: RECORD_MS,
    cases,
    source: m8SortTimeline.toString(),
  };
}
